window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-47cba016b23ccd91"]={"versions": [{"id": "FIG-47cba016b23ccd91", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR Timing Extensions (TPS Timing Extensions). Das Diagramm definiert das Metamodell für VFB-bezogene Timing-Ereignisse an Variablen-Datenprototypen (<code>TDEventVariableDataPrototype</code>) im Kontext der virtuellen Funktionsbus-Ebene (VFB).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Modellelemente:</p>\n<ul class=\"fig-list\">\n<li><code>TimingDescriptionEvent::TDEventVfb::TDEventVfb</code>: Abstrakte Basisklasse für VFB-Timing-Ereignisse.</li>\n<li><code>TDEventVfb::TDEventVfbPort</code>: Spezialisierung von <code>TDEventVfb</code>, versehen mit dem Attribut <code>+ isExternal :Boolean</code>.</li>\n<li><code>TDEventVariableDataPrototype</code>: Spezialisierung von <code>TDEventVfbPort</code>. Besitzt das Attribut <code>+ tdEventVariableDataPrototypeType :TDEventVariableDataPrototypeTypeEnum</code>.</li>\n<li><code>«enumeration» TDEventVariableDataPrototypeTypeEnum</code>: Aufzählungstyp mit den Literalen <code>variableDataPrototypeSent</code> und <code>variableDataPrototypeReceived</code>.</li>\n<li><code>AutosarDataPrototype::DataPrototypes::VariableDataPrototype</code>: Zielklasse einer gerichteten Assoziation von <code>TDEventVariableDataPrototype</code> mit Rollenname <code>+dataElement</code> und Multiplizität <code>1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdarstellung. Die Semantik beschreibt Zeitpunkte des Sendens (<code>variableDataPrototypeSent</code>) oder Empfangens (<code>variableDataPrototypeReceived</code>) bezüglich genau eines referenzierten Variablen-Datenprototyps (<code>VariableDataPrototype</code>) über einen Port, klassifiziert als intern oder extern (<code>isExternal</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Modellierer und Werkzeugentwickler der AUTOSAR Timing Extensions: <code>TDEventVariableDataPrototype</code> erfordert zwingend die Zuordnung genau eines <code>VariableDataPrototype</code> (<code>dataElement</code>, Multiplizität 1) sowie die Spezifikation des Ereignistyps über <code>tdEventVariableDataPrototypeType</code>. Das Attribut <code>isExternal</code> kennzeichnet, ob das Ereignis an der Außengrenze einer Komponente auftritt.</p>"}, {"id": "FIG-6f79053432985299", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR Timing Extensions (TPS Timing Extensions). Das Diagramm definiert das Metamodell für VFB-bezogene Timing-Ereignisse an Variablen-Datenprototypen (<code>TDEventVariableDataPrototype</code>) im Kontext der virtuellen Funktionsbus-Ebene (VFB).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Modellelemente:</p>\n<ul class=\"fig-list\">\n<li><code>TimingDescriptionEvent::TDEventVfb::TDEventVfb</code>: Abstrakte Basisklasse für VFB-Timing-Ereignisse.</li>\n<li><code>TDEventVfb::TDEventVfbPort</code>: Spezialisierung von <code>TDEventVfb</code>, versehen mit dem Attribut <code>+ isExternal :Boolean</code>.</li>\n<li><code>TDEventVariableDataPrototype</code>: Spezialisierung von <code>TDEventVfbPort</code>. Besitzt das Attribut <code>+ tdEventVariableDataPrototypeType :TDEventVariableDataPrototypeTypeEnum</code>.</li>\n<li><code>«enumeration» TDEventVariableDataPrototypeTypeEnum</code>: Aufzählungstyp mit den Literalen <code>variableDataPrototypeSent</code> und <code>variableDataPrototypeReceived</code>.</li>\n<li><code>AutosarDataPrototype::DataPrototypes::VariableDataPrototype</code>: Zielklasse einer gerichteten Assoziation von <code>TDEventVariableDataPrototype</code> mit Rollenname <code>+dataElement</code> und Multiplizität <code>1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdarstellung. Die Semantik beschreibt Zeitpunkte des Sendens (<code>variableDataPrototypeSent</code>) oder Empfangens (<code>variableDataPrototypeReceived</code>) bezüglich genau eines referenzierten Variablen-Datenprototyps (<code>VariableDataPrototype</code>) über einen Port, klassifiziert als intern oder extern (<code>isExternal</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Modellierer und Werkzeugentwickler der AUTOSAR Timing Extensions: <code>TDEventVariableDataPrototype</code> erfordert zwingend die Zuordnung genau eines <code>VariableDataPrototype</code> (<code>dataElement</code>, Multiplizität 1) sowie die Spezifikation des Ereignistyps über <code>tdEventVariableDataPrototypeType</code>. Das Attribut <code>isExternal</code> kennzeichnet, ob das Ereignis an der Außengrenze einer Komponente auftritt.</p>"}, {"id": "FIG-e8f6f87ad3e54257", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR Timing Extensions (TPS Timing Extensions). Das Diagramm definiert das Metamodell für VFB-bezogene Timing-Ereignisse an Variablen-Datenprototypen (<code>TDEventVariableDataPrototype</code>) im Kontext der virtuellen Funktionsbus-Ebene (VFB).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Modellelemente:</p>\n<ul class=\"fig-list\">\n<li><code>TimingDescriptionEvent::TDEventVfb</code>: Abstrakte Basisklasse für VFB-Timing-Ereignisse.</li>\n<li><code>TDEventVfbPort</code>: Spezialisierung von <code>TDEventVfb</code>, versehen mit dem Attribut <code>+ isExternal :Boolean</code>.</li>\n<li><code>TDEventVariableDataPrototype</code>: Spezialisierung von <code>TDEventVfbPort</code>. Besitzt das Attribut <code>+ tdEventVariableDataPrototypeType :TDEventVariableDataPrototypeTypeEnum</code>.</li>\n<li><code>«enumeration» TDEventVariableDataPrototypeTypeEnum</code>: Aufzählungstyp mit den Literalen <code>variableDataPrototypeSent</code> und <code>variableDataPrototypeReceived</code>.</li>\n<li><code>AutosarDataPrototype::VariableDataPrototype</code>: Zielklasse einer gerichteten Assoziation von <code>TDEventVariableDataPrototype</code> mit Rollenname <code>+dataElement</code> und Multiplizität <code>1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdarstellung. Die Semantik beschreibt Zeitpunkte des Sendens (<code>variableDataPrototypeSent</code>) oder Empfangens (<code>variableDataPrototypeReceived</code>) bezüglich genau eines referenzierten Variablen-Datenprototyps (<code>VariableDataPrototype</code>) über einen Port, klassifiziert als intern oder extern (<code>isExternal</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Modellierer und Werkzeugentwickler der AUTOSAR Timing Extensions: <code>TDEventVariableDataPrototype</code> erfordert zwingend die Zuordnung genau eines <code>VariableDataPrototype</code> (<code>dataElement</code>, Multiplizität 1) sowie die Spezifikation des Ereignistyps über <code>tdEventVariableDataPrototypeType</code>. Das Attribut <code>isExternal</code> kennzeichnet, ob das Ereignis an der Außengrenze einer Komponente auftritt.</p>"}, {"id": "FIG-6fe32773ca89cabc", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR Timing Extensions (TPS Timing Extensions). Das Diagramm definiert das Metamodell für VFB-bezogene Timing-Ereignisse an Variablen-Datenprototypen (<code>TDEventVariableDataPrototype</code>) im Kontext der virtuellen Funktionsbus-Ebene (VFB).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Modellelemente:</p>\n<ul class=\"fig-list\">\n<li><code>TimingDescriptionEvent::TDEventVfb</code>: Abstrakte Basisklasse für VFB-Timing-Ereignisse.</li>\n<li><code>TDEventVfbPort</code>: Spezialisierung von <code>TDEventVfb</code>, versehen mit dem Attribut <code>+ isExternal: Boolean</code>. Weist eine gerichtete Assoziation <code>+port</code> mit Multiplizität <code>0..1</code> auf <code>PortPrototype</code> auf.</li>\n<li><code>PortPrototype</code>: Zielklasse der Assoziation <code>+port</code>, versehen mit den Stereotypen <code>«AtpBlueprintable»</code> und <code>«AtpPrototype»</code>.</li>\n<li><code>TDEventVariableDataPrototype</code>: Spezialisierung von <code>TDEventVfbPort</code>. Besitzt das Attribut <code>+ tdEventVariableDataPrototypeType: TDEventVariableDataPrototypeTypeEnum</code>.</li>\n<li><code>«enumeration» TDEventVariableDataPrototypeTypeEnum</code>: Aufzählungstyp mit den Literalen <code>variableDataPrototypeSent</code> und <code>variableDataPrototypeReceived</code>.</li>\n<li><code>AutosarDataPrototype::VariableDataPrototype</code>: Zielklasse einer gerichteten Assoziation von <code>TDEventVariableDataPrototype</code> mit Rollenname <code>+dataElement</code> und Multiplizität <code>1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdarstellung. Die Semantik beschreibt Zeitpunkte des Sendens (<code>variableDataPrototypeSent</code>) oder Empfangens (<code>variableDataPrototypeReceived</code>) bezüglich genau eines referenzierten Variablen-Datenprototyps (<code>VariableDataPrototype</code>) über einen Port, klassifiziert als intern oder extern (<code>isExternal</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Modellierer und Werkzeugentwickler der AUTOSAR Timing Extensions: <code>TDEventVariableDataPrototype</code> erfordert die Zuordnung genau eines <code>VariableDataPrototype</code> (<code>dataElement</code>, Multiplizität 1) sowie die Spezifikation des Ereignistyps über <code>tdEventVariableDataPrototypeType</code>. Über die geerbte Assoziation <code>+port</code> von <code>TDEventVfbPort</code> kann optional (<code>0..1</code>) der zugehörige <code>PortPrototype</code> referenziert werden. Das Attribut <code>isExternal</code> kennzeichnet, ob das Ereignis an der Außengrenze auftritt.</p>"}, {"id": "FIG-c265e69c83a084e9", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR Timing Extensions (TPS Timing Extensions). Das Diagramm definiert das Metamodell für VFB-bezogene Timing-Ereignisse an Variablen-Datenprototypen (<code>TDEventVariableDataPrototype</code>) im Kontext der virtuellen Funktionsbus-Ebene (VFB).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Modellelemente:</p>\n<ul class=\"fig-list\">\n<li><code>TimingDescriptionEvent::TDEventVfb</code>: Abstrakte Basisklasse für VFB-Timing-Ereignisse.</li>\n<li><code>TDEventVfbPort</code>: Spezialisierung von <code>TDEventVfb</code>, versehen mit dem Attribut <code>+ isExternal: Boolean</code>. Weist eine gerichtete Assoziation <code>+port</code> mit Multiplizität <code>0..1</code> auf <code>PortPrototype</code> auf.</li>\n<li><code>PortPrototype</code>: Zielklasse der Assoziation <code>+port</code>, versehen mit den Stereotypen <code>«AtpBlueprintable»</code> und <code>«AtpPrototype»</code>.</li>\n<li><code>TDEventVariableDataPrototype</code>: Spezialisierung von <code>TDEventVfbPort</code>. Besitzt das Attribut <code>+ tdEventVariableDataPrototypeType: TDEventVariableDataPrototypeTypeEnum</code>.</li>\n<li><code>«enumeration» TDEventVariableDataPrototypeTypeEnum</code>: Aufzählungstyp mit den Literalen <code>variableDataPrototypeSent</code> und <code>variableDataPrototypeReceived</code>.</li>\n<li><code>AutosarDataPrototype::VariableDataPrototype</code>: Zielklasse einer gerichteten Assoziation von <code>TDEventVariableDataPrototype</code> mit Rollenname <code>+dataElement</code> und Multiplizität <code>1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdarstellung. Die Semantik beschreibt Zeitpunkte des Sendens (<code>variableDataPrototypeSent</code>) oder Empfangens (<code>variableDataPrototypeReceived</code>) bezüglich genau eines referenzierten Variablen-Datenprototyps (<code>VariableDataPrototype</code>) über einen Port, klassifiziert als intern oder extern (<code>isExternal</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Modellierer und Werkzeugentwickler der AUTOSAR Timing Extensions: <code>TDEventVariableDataPrototype</code> erfordert die Zuordnung genau eines <code>VariableDataPrototype</code> (<code>dataElement</code>, Multiplizität 1) sowie die Spezifikation des Ereignistyps über <code>tdEventVariableDataPrototypeType</code>. Über die geerbte Assoziation <code>+port</code> von <code>TDEventVfbPort</code> kann optional (<code>0..1</code>) der zugehörige <code>PortPrototype</code> referenziert werden. Das Attribut <code>isExternal</code> kennzeichnet, ob das Ereignis an der Außengrenze auftritt.</p>"}, {"id": "FIG-5540c6a5298cebe8", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR Timing Extensions (TPS Timing Extensions). Das Diagramm definiert das Metamodell für VFB-bezogene Timing-Ereignisse an Variablen-Datenprototypen (<code>TDEventVariableDataPrototype</code>) im Kontext der virtuellen Funktionsbus-Ebene (VFB).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Modellelemente:</p>\n<ul class=\"fig-list\">\n<li><code>TimingDescriptionEvent::TDEventVfb</code>: Abstrakte Basisklasse für VFB-Timing-Ereignisse.</li>\n<li><code>TDEventVfbPort</code>: Spezialisierung von <code>TDEventVfb</code>, versehen mit dem Attribut <code>+ isExternal: Boolean</code>. Weist eine gerichtete Assoziation <code>+port</code> mit Multiplizität <code>0..1</code> auf <code>PortPrototype</code> auf.</li>\n<li><code>PortPrototype</code>: Zielklasse der Assoziation <code>+port</code>, versehen mit den Stereotypen <code>«AtpBlueprintable»</code> und <code>«AtpPrototype»</code>.</li>\n<li><code>TDEventVariableDataPrototype</code>: Spezialisierung von <code>TDEventVfbPort</code>. Besitzt das Attribut <code>+ tdEventVariableDataPrototypeType: TDEventVariableDataPrototypeTypeEnum</code>.</li>\n<li><code>«enumeration» TDEventVariableDataPrototypeTypeEnum</code>: Aufzählungstyp mit den Literalen <code>variableDataPrototypeSent</code> und <code>variableDataPrototypeReceived</code>.</li>\n<li><code>AutosarDataPrototype::VariableDataPrototype</code>: Zielklasse einer gerichteten Assoziation von <code>TDEventVariableDataPrototype</code> mit Rollenname <code>+dataElement</code> und Multiplizität <code>1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdarstellung. Die Semantik beschreibt Zeitpunkte des Sendens (<code>variableDataPrototypeSent</code>) oder Empfangens (<code>variableDataPrototypeReceived</code>) bezüglich genau eines referenzierten Variablen-Datenprototyps (<code>VariableDataPrototype</code>) über einen Port, klassifiziert als intern oder extern (<code>isExternal</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Modellierer und Werkzeugentwickler der AUTOSAR Timing Extensions: <code>TDEventVariableDataPrototype</code> erfordert die Zuordnung genau eines <code>VariableDataPrototype</code> (<code>dataElement</code>, Multiplizität 1) sowie die Spezifikation des Ereignistyps über <code>tdEventVariableDataPrototypeType</code>. Über die geerbte Assoziation <code>+port</code> von <code>TDEventVfbPort</code> kann optional (<code>0..1</code>) der zugehörige <code>PortPrototype</code> referenziert werden. Das Attribut <code>isExternal</code> kennzeichnet, ob das Ereignis an der Außengrenze auftritt.</p>"}], "trans": [{"from": "FIG-47cba016b23ccd91", "to": "FIG-6f79053432985299", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6f79053432985299", "to": "FIG-e8f6f87ad3e54257", "fr": "R4.2.2", "tr": "R4.3.1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>In den Klassenkästen <code>TDEventVfb</code>, <code>TDEventVfbPort</code> und <code>VariableDataPrototype</code> entfällt jeweils der vorangestellte Paketpräfix (<code>TDEventVfb::</code> bzw. <code>DataPrototypes::</code>).</li>\n</ul>"}, {"from": "FIG-e8f6f87ad3e54257", "to": "FIG-6fe32773ca89cabc", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Klasse <code>PortPrototype</code> (mit den Stereotypen <code>«AtpBlueprintable»</code> und <code>«AtpPrototype»</code>) neu aufgenommen.</li>\n<li>Gerichtete Assoziation <code>+port</code> mit Multiplizität <code>0..1</code> von <code>TDEventVfbPort</code> zu <code>PortPrototype</code> ergänzt.</li>\n<li>Typdeklarationen bei Attributen formatiert (<code>: Boolean</code> statt <code>:Boolean</code>, <code>: TDEventVariableDataPrototypeTypeEnum</code> statt <code>:TDEventVariableDataPrototypeTypeEnum</code>).</li>\n</ul>"}, {"from": "FIG-6fe32773ca89cabc", "to": "FIG-c265e69c83a084e9", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c265e69c83a084e9", "to": "FIG-5540c6a5298cebe8", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
